        { "question": "New Q2", "options": ["X", "Y"], "correctIndex": 1, "explanation": "E2", "sourcePage": null },
        { "question": "New Q3", "options": ["X", "Y"], "correctIndex": 0, "explanation": "E3", "sourcePage": null }
