            [],
            |r| r.get(0),
        )
        .unwrap();
    assert_eq!(active_ver, ver_id);

    // In-progress attempt is still in_progress with its response and revision intact
    let (status, rev, ans_count): (String, i64, i64) = conn2
        .query_row(
