        correct_index: 0,
        explanation: "".to_string(),
        source_page: None,
    };
    let hash = compute_canonical_content_hash_from_parsed(&[q1]);
    let expected_json = r#"[{"correctIndex":0,"explanation":"","options":["A","B"],"question":"Synthetic question","sourcePage":null}]"#;
