    // Selected index provided when isDontKnow is true
    await expect(
      repo.saveSessionAction({
        action: "record_response",
        operationId: crypto.randomUUID(),
        attemptId: start.attemptId,
        itemId: active.items[0]!.id,
        expectedRevision: 0,
        selectedIndex: 0,
        isDontKnow: true,
      }),
